def file_name_check(file_name):
    # Condition: exactly one dot
    if file_name.count('.') != 1:
        return 'No'

    before, after = file_name.split('.')

    # Condition: substring before dot is not empty and starts with a latin letter
    if len(before) == 0:
        return 'No'
    first_char = before[0]
    if not (('a' <= first_char <= 'z') or ('A' <= first_char <= 'Z')):
        return 'No'

    # Condition: substring after dot is one of ['txt', 'exe', 'dll']
    if after not in ['txt', 'exe', 'dll']:
        return 'No'

    # Condition: no more than three digits in the whole file name
    digit_count = sum(1 for c in file_name if c.isdigit())
    if digit_count > 3:
        return 'No'

    return 'Yes'

